                if (user.ProviderOption.Value != null)
                    writer.WriteString("provider", user.Provider);
                else
                    writer.WriteNull("provider");

            if (user.SectorIdOption.IsSet)
                if (user.SectorIdOption.Value != null)
                    writer.WriteNumber("sector_id", user.SectorIdOption.Value!.Value);
                else
                    writer.WriteNull("sector_id");

            if (user.OrganisationOption.IsSet)
                if (user.OrganisationOption.Value != null)
                    writer.WriteString("organisation", user.Organisation);
                else
                    writer.WriteNull("organisation");

            if (user.BioOption.IsSet)
                if (user.BioOption.Value != null)
                    writer.WriteString("bio", user.Bio);
                else
                    writer.WriteNull("bio");

            if (user.DomainOption.IsSet)
                if (user.DomainOption.Value != null)
                    writer.WriteString("domain", user.Domain);
                else
                    writer.WriteNull("domain");

            if (user.LinkOption.IsSet)
                if (user.LinkOption.Value != null)
                    writer.WriteString("link", user.Link);
                else
                    writer.WriteNull("link");

            if (user.OrcidOption.IsSet)
                if (user.OrcidOption.Value != null)
                    writer.WriteString("orcid", user.Orcid);
                else
                    writer.WriteNull("orcid");

            if (user.ContactFeedbackOption.IsSet)
                if (user.ContactFeedbackOption.Value != null)
                    writer.WriteBoolean("contact_feedback", user.ContactFeedbackOption.Value!.Value);
                else
                    writer.WriteNull("contact_feedback");

            if (user.ContactNewsOption.IsSet)
                if (user.ContactNewsOption.Value != null)
                    writer.WriteBoolean("contact_news", user.ContactNewsOption.Value!.Value);
                else
                    writer.WriteNull("contact_news");

            if (user.IsAdminOption.IsSet)
                writer.WriteBoolean("is_admin", user.IsAdminOption.Value!.Value);

            if (user.TermsOption.IsSet)
                writer.WriteBoolean("terms", user.TermsOption.Value!.Value);

            if (user.CreatedAtOption.IsSet)
                writer.WriteString("created_at", user.CreatedAtOption.Value!.Value.ToString(CreatedAtFormat));

            if (user.UpdatedAtOption.IsSet)
                writer.WriteString("updated_at", user.UpdatedAtOption.Value!.Value.ToString(UpdatedAtFormat));
        }
    }
}
